const tasks = $input.first().json.result || [];
console.log(`Total tasks found: ${tasks.length}`);

const allTasks = [];
const ddTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const titleLower = title.toLowerCase();

  allTasks.push({
    id: task.id,
    title: title,
    is_due_diligence: titleLower.includes('due diligence')
  });

  if (titleLower.includes('due diligence')) {
    ddTasks.push({
      id: task.id,
      title: title,
      description: task.description || ''
    });
  }
}

console.log('📋 All tasks:', allTasks);
console.log('🎯 Due Diligence tasks:', ddTasks);

return [{
  json: {
    total_tasks: tasks.length,
    all_tasks: allTasks,
    dd_tasks: ddTasks,
    dd_count: ddTasks.length,
    message: ddTasks.length > 0 
      ? `Found ${ddTasks.length} Due Diligence tasks` 
      : 'No Due Diligence tasks found. Create a task with title containing "Due Diligence"'
  }
}];
